import { htmlTemplates } from "./html-templates.js";

// Command handlers with optimized logic
export const commandHandlers = {
  whoami: () => htmlTemplates.whoami(),

  pwd: () =>
    `<div class="text-cyan-400 font-bold">/Users/sandeep/portfolio</div>`,

  date: () =>
    `<div class="text-green-400 font-bold">${new Date().toString()}</div>`,

  uptime: () => htmlTemplates.uptime(),

  ps: () => htmlTemplates.ps(),

  env: () => htmlTemplates.env(),

  cat: (args, data) => {
    if (!args || args.length === 0) {
      return htmlTemplates.catError();
    }

    const filename = args[0];
    return htmlTemplates.catFile(filename, data);
  },

  grep: (args, data) => {
    if (!args || args.length === 0) {
      return htmlTemplates.grepError();
    }

    const searchTerm = args[0].toLowerCase();
    const filename = args[1];

    return htmlTemplates.grepResults(searchTerm, filename, data);
  },

  file: (args, data) => {
    if (!args || args.length === 0) {
      return `<div class="text-red-400 font-bold">file: missing file operand</div>`;
    }

    const filename = args[0];
    const fileType = data.fileTypes[filename];

    return fileType
      ? `<div class="text-gray-100">${filename}: <span class="text-cyan-400">${fileType}</span></div>`
      : `<div class="text-red-400 font-bold">file: cannot open '${filename}' (No such file or directory)</div>`;
  },

  about: (args, data) => htmlTemplates.about(data),

  experience: (args, data) => htmlTemplates.experience(data),

  education: (args, data) => htmlTemplates.education(data),

  projects: (args, data) => htmlTemplates.projects(data),

  skills: (args, data) => htmlTemplates.skills(data),

  contact: (args, data) => htmlTemplates.contact(data),

  ls: () => htmlTemplates.ls(),

  help: () => htmlTemplates.help(),
};
