  grepResults: (searchTerm, filename, data) => {
    const searchContent = {
      portfolio: `${data.personal.name} Full Stack Engineer ${data.personal.experience} experience LAMP MEVN MERN stack Laravel Node.js Vue.js React.js PHP Python MySQL MongoDB WordPress AWS Lambda API Development Git ${data.personal.company}`,
      "about.txt": `${data.personal.name} Full Stack Engineer ${data.personal.experience} experience LAMP MEVN MERN stack ${data.personal.company} ${data.personal.location}`,
      "experience.txt": data.experience
        .map((exp) => `${exp.company} ${exp.tech}`)
        .join(" "),
      "skills.txt": Object.values(data.skills)
        .flat()
        .map((skill) => skill.name)
        .join(" "),
      "projects.txt": data.projects
        .map((project) => `${project.name} ${project.tech.join(" ")}`)
        .join(" "),
    };

    const results = [];

    if (filename && searchContent[filename]) {
      const content = searchContent[filename];
      if (content.toLowerCase().includes(searchTerm)) {
        results.push(
          `<div class="text-yellow-400 font-bold">${filename}:</div><div class="text-gray-100">Found matches for "<span class="text-green-400">${searchTerm}</span>"</div>`
        );
      }
    } else {
      Object.keys(searchContent).forEach((file) => {
        if (searchContent[file].toLowerCase().includes(searchTerm)) {
          results.push(
            `<div class="text-yellow-400 font-bold">${file}:</div><div class="text-gray-100">Found matches for "<span class="text-green-400">${searchTerm}</span>"</div>`
          );
        }
      });
    }

    return results.length > 0
      ? results.join("<br>")
      : `<div class="text-gray-300">No matches found for "<span class="text-red-400">${searchTerm}</span>"</div>`;
  },

