<template>
  <div class="min-h-screen bg-black text-green-400 font-mono p-2 sm:p-4">
    <div class="max-w-5xl mx-auto rounded-2xl">
      <!-- Terminal Header -->
      <div
        class="bg-gray-800 rounded-t-lg p-2 sm:p-3 flex items-center space-x-2 border-b border-gray-700"
      >
        <div
          class="w-3 h-3 bg-red-500 rounded-full hover:bg-red-400 transition-colors cursor-pointer"
        ></div>
        <div
          class="w-3 h-3 bg-yellow-500 rounded-full hover:bg-yellow-400 transition-colors cursor-pointer"
        ></div>
        <div
          class="w-3 h-3 bg-green-500 rounded-full hover:bg-green-400 transition-colors cursor-pointer"
        ></div>
        <span class="text-gray-300 text-xs sm:text-sm ml-2 truncate">
          sandeep@portfolio — zsh
        </span>
      </div>

      <!-- Terminal Content -->
      <div
        class="bg-black rounded-b-lg p-3 sm:p-6 border-2 border-gray-800 overflow-y-auto max-h-[calc(100vh-120px)]"
      >
        <!-- Welcome Message -->
        <div class="mb-4 sm:mb-6">
          <div class="text-green-400 text-xs sm:text-sm">
            Last login: {{ currentDate }} on ttys001
          </div>
          <div class="text-green-400 mt-3 sm:mt-4">
            <pre class="text-xs sm:text-sm leading-tight">{{ asciiArt }}</pre>
          </div>
        </div>

        <!-- Command History -->
        <div
          v-for="(command, index) in displayedHistory"
          :key="`cmd-${index}`"
          class="mb-3 sm:mb-4"
        >
          <div class="flex flex-wrap items-center text-xs sm:text-sm">
            <span class="text-green-400 font-bold">sandeep@portfolio</span>
            <span class="text-gray-300 mx-1">:</span>
            <span class="text-blue-400 font-bold">~</span>
            <span class="text-gray-300 ml-2">$</span>
            <span class="text-gray-100 ml-2 break-all">{{
              command.input
            }}</span>
          </div>
          <div
            v-html="command.output"
            class="mt-1 sm:mt-2 text-xs sm:text-sm"
          ></div>
        </div>

        <!-- Current Input -->
        <div class="flex items-center text-xs sm:text-sm">
          <span class="text-green-400 font-bold">sandeep@portfolio</span>
          <span class="text-gray-300 mx-1">:</span>
          <span class="text-blue-400 font-bold">~</span>
          <span class="text-gray-300 ml-2">$</span>
          <input
            ref="commandInput"
            v-model="currentCommand"
            @keyup.enter="executeCommand"
            @keyup.up="navigateHistory(-1)"
            @keyup.down="navigateHistory(1)"
            class="bg-black text-gray-100 outline-none flex-1 ml-2 placeholder-gray-500 border-none text-xs sm:text-sm"
            placeholder="Type 'help' to see available commands"
            autofocus
          />
          <span class="text-green-400 animate-pulse font-bold text-lg">█</span>
        </div>

        <!-- Help Text -->
        <div
          v-if="showHelp"
          class="mt-4 sm:mt-6 text-gray-300 text-xs sm:text-sm"
        >
          <div class="text-yellow-400 mb-2">
            💡 Available commands: help, about, experience, education, projects,
            skills, contact, clear, ls
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, nextTick } from "vue";
import { commandHandlers } from "./utils/command-handlers.js";
import { portfolioData } from "./utils/portfolio-data.js";
import { htmlTemplates } from "./utils/html-templates.js";

// Reactive state
const currentCommand = ref("");
const commandHistory = ref([]);
const inputHistory = ref([]);
const historyIndex = ref(-1);
const showHelp = ref(true);
const commandInput = ref(null);

// Constants
const MAX_HISTORY_SIZE = 50;
const DISPLAY_HISTORY_SIZE = 30;

// Computed properties
const currentDate = computed(() => {
  return new Date().toLocaleDateString("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
});

const asciiArt = computed(() => portfolioData.asciiArt);

const displayedHistory = computed(() => {
  return commandHistory.value.slice(-DISPLAY_HISTORY_SIZE);
});

// Command execution
const executeCommand = async () => {
  const command = currentCommand.value.trim();
  if (!command) return;

  inputHistory.value.unshift(command);
  if (inputHistory.value.length > MAX_HISTORY_SIZE) {
    inputHistory.value = inputHistory.value.slice(0, MAX_HISTORY_SIZE);
  }
  historyIndex.value = -1;

  if (command === "clear") {
    commandHistory.value = [];
    showHelp.value = false;
  } else {
    const output = await getCommandOutput(command.toLowerCase());
    const commandObj = {
      input: command,
      output: output || getErrorOutput(command.split(" ")[0]),
    };

    commandHistory.value.push(commandObj);

    if (commandHistory.value.length > MAX_HISTORY_SIZE) {
      commandHistory.value = commandHistory.value.slice(-MAX_HISTORY_SIZE);
    }

    showHelp.value = false;
  }

  currentCommand.value = "";

  await nextTick();
  window.scrollTo(0, document.body.scrollHeight);
};

const getCommandOutput = async (cmd) => {
  const parts = cmd.split(" ");
  const command = parts[0];
  const args = parts.slice(1);

  if (command === "history") {
    return htmlTemplates.history(inputHistory.value);
  }

  if (commandHandlers[command]) {
    return commandHandlers[command](args, portfolioData);
  }

  return null;
};

const getErrorOutput = (command) => {
  return `<div class="text-red-400 font-bold">bash: ${command}: command not found</div><div class="text-gray-300 text-sm mt-1">Type <span class="text-cyan-400 font-bold">'help'</span> to see available commands</div>`;
};

const navigateHistory = (direction) => {
  if (inputHistory.value.length === 0) return;

  historyIndex.value += direction;

  if (historyIndex.value < 0) {
    historyIndex.value = -1;
    currentCommand.value = "";
  } else if (historyIndex.value >= inputHistory.value.length) {
    historyIndex.value = inputHistory.value.length - 1;
  }

  if (historyIndex.value >= 0) {
    currentCommand.value = inputHistory.value[historyIndex.value];
  }
};

const focusInput = () => {
  if (commandInput.value) {
    commandInput.value.focus();
  }
};

onMounted(() => {
  focusInput();
  setTimeout(() => {
    commandHistory.value.push({
      input: "whoami",
      output: commandHandlers.whoami([], portfolioData),
    });
    showHelp.value = false;
  }, 1000);
});

document.addEventListener("click", focusInput);
</script>

